from pathlib import Path
r=Path(__file__).resolve().parents[2];o=r/'artifacts/replica/windows-download';src=(r/'docs/replica/source/original.js').read_text().splitlines()
defs='\n'.join(x for x in src if x.startswith(('const PAPER=','let lang=','const t=','const icons=','const icon=','const btn=','const heading=','function home(')))
script=defs+"\nlet lang='ko';\n"+'''
const cases=[];
for(const language of ['ko','en'])for(const width of [270,300,375.2,520]){lang=language;const h=document.createElement('div');h.innerHTML=home();const card=h.querySelector('.sample-report');const id=`${language}-${width}`;card.dataset.id=id;const f=document.createElement('div');f.className='fixture';f.style.width=width+'px';f.append(card);document.getElementById('fixtures').append(f);cases.push({id,width,english:language==='en'})}
function read(){return [...document.querySelectorAll('.sample-report')].map(e=>{const r=e.getBoundingClientRect(),box=x=>{const b=x.getBoundingClientRect();return{x:b.x-r.x,y:b.y-r.y,width:b.width,height:b.height}},text=x=>({box:box(x),text:[...x.childNodes].map(n=>n.nodeName==='BR'?'\\n':n.textContent).join(''),color:getComputedStyle(x).color});return{id:e.dataset.id,root:box(e),head:box(e.querySelector('.report-head')),headText:text(e.querySelector('.report-head span')),icon:box(e.querySelector('.svg')),title:text(e.querySelector('.report-title')),lines:[...e.querySelectorAll('.report-line')].map(x=>({box:box(x),label:text(x.querySelector('span')),value:text(x.querySelector('b'))})),foot:text(e.querySelector('.report-foot')),name:e.getAttribute('aria-label'),background:getComputedStyle(e).backgroundColor,border:getComputedStyle(e).borderColor,radius:parseFloat(getComputedStyle(e).borderRadius)}})}function getCases(){return cases}
'''
(o/'samplereport-original.css').write_bytes((r/'docs/replica/source/original.css').read_bytes())
(o/'samplereport-inner.html').write_text('<!doctype html><meta charset="utf-8"><link rel="stylesheet" href="samplereport-original.css"><style>.fixture{position:absolute;left:30px;top:60px}.fixture:not(:first-child){visibility:hidden}.sample-report{display:block!important}</style><div id="fixtures"></div><script>'+script+'</script>')
(o/'samplereport.html').write_text('''<!doctype html><meta charset="utf-8"><title>SampleReport · original isolation</title><button id="samplereport-record">Record SampleReport</button><iframe width="1400" height="650" src="samplereport-inner.html"></iframe><script>document.getElementById('samplereport-record').onclick=async()=>{const f=document.querySelector('iframe');await f.contentDocument.fonts.ready;const res=await fetch('/evidence/source-sidebar.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dpr:devicePixelRatio,rows:f.contentWindow.read(),cases:f.contentWindow.getCases()})});if(!res.ok)throw Error('Record failed');document.getElementById('samplereport-record').textContent='SampleReport recorded'}</script>''')
print('8 literal sample report cases')
